import type { RawMesh, Vec3 } from '../types';

/** Built-in shapes, generated by us (no third-party models). Sizes are in millimetres. */

export function cube(size: number): RawMesh {
  const h = size / 2;
  const positions: Vec3[] = [
    [-h, -h, -h], [h, -h, -h], [h, h, -h], [-h, h, -h],
    [-h, -h, h], [h, -h, h], [h, h, h], [-h, h, h],
  ];
  return {
    positions,
    faces: [
      [0, 3, 2, 1], [4, 5, 6, 7], [0, 1, 5, 4], [2, 3, 7, 6], [1, 2, 6, 5], [3, 0, 4, 7],
    ],
  };
}

export function box(width: number, depth: number, height: number): RawMesh {
  const m = cube(1);
  return { positions: m.positions.map(([x, y, z]): Vec3 => [x * width, y * depth, z * height]), faces: m.faces };
}

export function tetrahedron(edge: number): RawMesh {
  const a = edge / Math.sqrt(8);
  const positions: Vec3[] = [[a, a, a], [a, -a, -a], [-a, a, -a], [-a, -a, a]];
  return { positions, faces: [[0, 1, 2], [0, 3, 1], [0, 2, 3], [1, 3, 2]] };
}

export function octahedron(edge: number): RawMesh {
  const r = edge / Math.SQRT2;
  const positions: Vec3[] = [[r, 0, 0], [-r, 0, 0], [0, r, 0], [0, -r, 0], [0, 0, r], [0, 0, -r]];
  return {
    positions,
    faces: [[0, 2, 4], [2, 1, 4], [1, 3, 4], [3, 0, 4], [2, 0, 5], [1, 2, 5], [3, 1, 5], [0, 3, 5]],
  };
}

export function icosahedron(edge: number): RawMesh {
  const t = (1 + Math.sqrt(5)) / 2;
  const s = edge / 2;
  const raw: Vec3[] = [
    [-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0],
    [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t],
    [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1],
  ];
  const positions = raw.map(([x, y, z]): Vec3 => [x * s, y * s, z * s]);
  return {
    positions,
    faces: [
      [0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11],
      [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
      [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9],
      [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1],
    ],
  };
}

export function dodecahedron(edge: number): RawMesh {
  const phi = (1 + Math.sqrt(5)) / 2;
  const s = edge / (2 / phi);
  const raw: Vec3[] = [];
  for (const x of [-1, 1]) for (const y of [-1, 1]) for (const z of [-1, 1]) raw.push([x, y, z]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([0, a / phi, b * phi]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([a / phi, b * phi, 0]);
  for (const a of [-1, 1]) for (const b of [-1, 1]) raw.push([a * phi, 0, b / phi]);
  const positions = raw.map(([x, y, z]): Vec3 => [x * s, y * s, z * s]);
  // Faces are found from the geometry: groups of five corners lying on one of the twelve face planes.
  const faces: number[][] = [];
  const dirs: Vec3[] = [];
  for (const a of [-1, 1]) for (const b of [-1, 1]) {
    dirs.push([a, 0, b * phi], [0, a * phi, b], [a * phi, b, 0]);
  }
  for (const d of dirs) {
    const len = Math.hypot(d[0], d[1], d[2]);
    const n: Vec3 = [d[0] / len, d[1] / len, d[2] / len];
    const dots = positions.map((p) => p[0] * n[0] + p[1] * n[1] + p[2] * n[2]);
    const top = Math.max(...dots);
    const ids = dots.map((v, i) => ({ v, i })).filter((e) => Math.abs(e.v - top) < 1e-6 * edge).map((e) => e.i);
    // Order the five corners around the normal.
    let cx = 0;
    let cy = 0;
    let cz = 0;
    for (const i of ids) {
      cx += positions[i][0] / ids.length;
      cy += positions[i][1] / ids.length;
      cz += positions[i][2] / ids.length;
    }
    const c: Vec3 = [cx, cy, cz];
    const ref = Math.abs(n[0]) < 0.9 ? ([1, 0, 0] as Vec3) : ([0, 1, 0] as Vec3);
    const u: Vec3 = [n[1] * ref[2] - n[2] * ref[1], n[2] * ref[0] - n[0] * ref[2], n[0] * ref[1] - n[1] * ref[0]];
    const ul = Math.hypot(u[0], u[1], u[2]);
    const uu: Vec3 = [u[0] / ul, u[1] / ul, u[2] / ul];
    const w: Vec3 = [n[1] * uu[2] - n[2] * uu[1], n[2] * uu[0] - n[0] * uu[2], n[0] * uu[1] - n[1] * uu[0]];
    ids.sort((p, q) => {
      const ang = (i: number) => {
        const d2: Vec3 = [positions[i][0] - c[0], positions[i][1] - c[1], positions[i][2] - c[2]];
        return Math.atan2(d2[0] * w[0] + d2[1] * w[1] + d2[2] * w[2], d2[0] * uu[0] + d2[1] * uu[1] + d2[2] * uu[2]);
      };
      return ang(p) - ang(q);
    });
    faces.push(ids);
  }
  return { positions, faces };
}

/** A prism with a regular n-gon base. */
export function prism(sides: number, radius: number, height: number): RawMesh {
  const positions: Vec3[] = [];
  for (const z of [0, height]) {
    for (let i = 0; i < sides; i++) {
      const a = (2 * Math.PI * i) / sides;
      positions.push([radius * Math.cos(a), radius * Math.sin(a), z]);
    }
  }
  const faces: number[][] = [Array.from({ length: sides }, (_, i) => sides - 1 - i), Array.from({ length: sides }, (_, i) => sides + i)];
  for (let i = 0; i < sides; i++) faces.push([i, (i + 1) % sides, sides + ((i + 1) % sides), sides + i]);
  return { positions, faces };
}

/** A pyramid with a regular n-gon base. */
export function pyramid(sides: number, radius: number, height: number): RawMesh {
  const positions: Vec3[] = [];
  for (let i = 0; i < sides; i++) {
    const a = (2 * Math.PI * i) / sides;
    positions.push([radius * Math.cos(a), radius * Math.sin(a), 0]);
  }
  positions.push([0, 0, height]);
  const faces: number[][] = [Array.from({ length: sides }, (_, i) => sides - 1 - i)];
  for (let i = 0; i < sides; i++) faces.push([i, (i + 1) % sides, sides]);
  return { positions, faces };
}

/**
 * A solid of revolution: `profile` is a list of [radius, height] from the bottom to the top. Radius 0 at an end
 * closes it with a point, a positive radius closes it with a flat cap. Gives gems, vases and bottles.
 */
export function lathe(profile: readonly [number, number][], segments: number): RawMesh {
  const positions: Vec3[] = [];
  const rings: number[][] = [];
  const poles: (number | null)[] = [null, null];
  profile.forEach(([r, h], pi) => {
    if (r === 0 && (pi === 0 || pi === profile.length - 1)) {
      poles[pi === 0 ? 0 : 1] = positions.length;
      positions.push([0, 0, h]);
      rings.push([]);
    } else {
      const ring: number[] = [];
      for (let i = 0; i < segments; i++) {
        const a = (2 * Math.PI * i) / segments;
        ring.push(positions.length);
        positions.push([r * Math.cos(a), r * Math.sin(a), h]);
      }
      rings.push(ring);
    }
  });
  const faces: number[][] = [];
  for (let p = 0; p + 1 < profile.length; p++) {
    const lo = rings[p];
    const hi = rings[p + 1];
    for (let i = 0; i < segments; i++) {
      const j = (i + 1) % segments;
      if (lo.length === 0) faces.push([poles[0]!, hi[j], hi[i]]);
      else if (hi.length === 0) faces.push([lo[i], lo[j], poles[1]!]);
      else faces.push([lo[i], lo[j], hi[j], hi[i]]);
    }
  }
  if (poles[0] === null) faces.push([...rings[0]].reverse());
  if (poles[1] === null) faces.push([...rings[rings.length - 1]]);
  return { positions, faces };
}

/** A low-poly gem (brilliant-style: a crown, a flat table and a pointed pavilion). */
export function gem(radius: number, segments = 8): RawMesh {
  return lathe(
    [[0, 0], [radius * 0.95, radius * 0.9], [radius, radius * 1.05], [radius * 0.5, radius * 1.35]],
    segments,
  );
}

/** A non-convex block: an L-shaped prism (tests concave edges and non-convex faces). */
export function lBlock(size: number): RawMesh {
  const u = size / 2;
  const outline: [number, number][] = [[0, 0], [2 * u, 0], [2 * u, u], [u, u], [u, 2 * u], [0, 2 * u]];
  const n = outline.length;
  const positions: Vec3[] = [...outline.map(([x, y]): Vec3 => [x, y, 0]), ...outline.map(([x, y]): Vec3 => [x, y, u])];
  const faces: number[][] = [Array.from({ length: n }, (_, i) => n - 1 - i), Array.from({ length: n }, (_, i) => n + i)];
  for (let i = 0; i < n; i++) faces.push([i, (i + 1) % n, n + ((i + 1) % n), n + i]);
  return { positions, faces };
}

export const BUILT_IN_SHAPES = {
  cube: (size = 50) => cube(size),
  tetrahedron: (size = 60) => tetrahedron(size),
  octahedron: (size = 50) => octahedron(size),
  icosahedron: (size = 40) => icosahedron(size),
  dodecahedron: (size = 30) => dodecahedron(size),
  gem: (size = 40) => gem(size),
  lBlock: (size = 60) => lBlock(size),
} as const;
